sys_script.script:
var gr = new GlideRecord('task');
gr.addQuery('active', true);
gr.query();
while (gr.next()) { gr.state = 3; gr.update(); }

var gr = new GlideRecord('task');
gr.addQuery('active', true);
gr.setLimit(100);
gr.query();

sys_script_include.script:
while (task.next()) {
  var u = new GlideRecord('sys_user');
  u.get(task.assigned_to);
}

var u = new GlideRecord('sys_user');
u.addQuery('active', true);
u.query();
while (u.next()) { total++; }

sys_script.script:
var a = new GlideRecord('sysapproval_approver');
a.addQuery('document_id', current.sys_id);
a.query();
g_scratchpad.count = a.getRowCount();

sys_script_include.script:
var gr = new GlideRecord('u_staging');
gr.addQuery('processed', true);
gr.deleteMultiple();

var n = 0;
while (gr.next()) { n++; }
return n;

var ga = new GlideAggregate('incident');
ga.addAggregate('COUNT');
ga.query();

sys_script.script:
var p = new GlideRecord('incident');
p.get(current.parent);
p.u_total = 1;
p.update();

sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
  g_form.setMandatory('cause_notes', newValue == 'closed');
}
